-- V20 Web Push keys (docs/ios/V20_LAUNCH.md). The VAPID key pair is generated by the push-delivery Edge Function on its
-- first run and kept here, readable only by the service role: the private key never leaves Supabase (no person or tool
-- ever handles it). Browsers read the public key through household_push_key() to subscribe.
create table public.household_push_keys (
  id boolean primary key default true check (id),
  public_key text not null,
  private_key text not null,
  created_at timestamptz not null default now()
);
alter table public.household_push_keys enable row level security;
revoke all on public.household_push_keys from public, anon, authenticated;
grant select, insert on public.household_push_keys to service_role;

create function public.household_push_key()
returns text language sql stable security definer set search_path = '' as $$
  select public_key from public.household_push_keys where id
$$;
revoke all on function public.household_push_key() from public, anon;
grant execute on function public.household_push_key() to authenticated;
-- Rollback: drop function public.household_push_key(); drop table public.household_push_keys;
